// InvoiceViewDto is `invoice.InvoiceViewDto`.
type InvoiceViewDto struct {
	ID string `json:"id"`

	// Jurisdiction Example: "NG".
	Jurisdiction string `json:"jurisdiction"`

	// InvoiceNumber The document’s own number, unique per organisation.
	// Example: "INV00042".
	InvoiceNumber string `json:"invoiceNumber"`

	// AuthorityInvoiceNumber The number NRS holds, once registered; null until then.
	AuthorityInvoiceNumber *string `json:"authorityInvoiceNumber"`

	// DisplayNumber The number to show: `authorityInvoiceNumber`, else `invoiceNumber`.
	DisplayNumber string `json:"displayNumber"`

	InvoiceType InvoiceViewDtoInvoiceType `json:"invoiceType"`

	// InvoiceKind Example: "B2B".
	InvoiceKind string `json:"invoiceKind"`

	Status InvoiceViewDtoStatus `json:"status"`

	// AuthorityState The current submission’s state.
	AuthorityState *InvoiceViewDtoAuthorityState `json:"authorityState"`

	// AuthorityReference The IRN, once assigned.
	AuthorityReference *string `json:"authorityReference"`

	// ParkReason Why the current submission is on hold.
	ParkReason *string `json:"parkReason"`

	// IssuedAs The identity the document was issued under; null until its first submission.
	IssuedAs *InvoiceIssuedAsDto `json:"issuedAs"`

	// IssueDate Example: "2026-09-30".
	IssueDate string `json:"issueDate"`

	// IssueTime Example: "14:30:00".
	IssueTime *string `json:"issueTime"`

	// DueDate Example: "2026-09-30".
	DueDate *string `json:"dueDate"`

	// Currency Example: "NGN".
	Currency string `json:"currency"`

	// TaxCurrency Example: "NGN".
	TaxCurrency string `json:"taxCurrency"`

	// Seller A draft shows the seller as it is now; a finalised document as it was when finalised.
	Seller *InvoiceSellerSnapshotDto `json:"seller"`

	// Buyer A draft shows the buyer as it is now; a finalised document as it was when finalised.
	Buyer *InvoiceBuyerSnapshotDto `json:"buyer"`

	// BuyerVerification The buyer’s verification as it stands now; null with no buyer or tax id, or once the buyer’s tax id differs from the document’s.
	BuyerVerification *InvoiceBuyerVerificationDto `json:"buyerVerification"`

	// LineItems The lines. Absent on list items.
	LineItems []InvoiceLineViewDto `json:"lineItems,omitempty"`

	Totals InvoiceTotalsDto `json:"totals"`

	TaxSubtotals []InvoiceTaxSubtotalDto `json:"taxSubtotals"`

	// PaymentStatus What the buyer paid (on a credit note: its refund status). Never moved by a cancellation.
	PaymentStatus InvoiceViewDtoPaymentStatus `json:"paymentStatus"`

	// AmountPaidMinor What the tax authority accepted as paid. Integer minor units.
	AmountPaidMinor int64 `json:"amountPaidMinor"`

	// CreditedMinor On an invoice: Σ its counting credit notes (0 when none). Null on a note. Integer minor units.
	CreditedMinor *int64 `json:"creditedMinor"`

	// DebitedMinor On an invoice: Σ its counting debit notes (0 when none). Null on a note. Integer minor units.
	DebitedMinor *int64 `json:"debitedMinor"`

	// NetReceivableMinor On an invoice: payable + debited − credited, never below zero (also what can still be credited). Null on a note. Integer minor units.
	NetReceivableMinor *int64 `json:"netReceivableMinor"`

	// CreditStatus On an invoice; null on a note.
	CreditStatus *InvoiceViewDtoCreditStatus `json:"creditStatus"`

	// Adjustments An invoice’s credit and debit notes, in issue order (empty on a note).
	Adjustments []InvoiceAdjustmentDto `json:"adjustments"`

	// CreditNoteSettlement On an invoice with a counting credit note, or on a credit note: settled, or a refund owed. Null otherwise.
	CreditNoteSettlement *InvoiceCreditSettlementDto `json:"creditNoteSettlement"`

	// RefundOwedMinor `creditNoteSettlement.refundOwedMinor`, or null with it. Integer minor units.
	RefundOwedMinor *int64 `json:"refundOwedMinor"`

	// PaymentCeilingMinor What "paid in full" records on this document: an invoice, its payable less its credit notes (debit notes are paid on themselves); a credit note, its share of the refund owed; a debit note, its payable. Integer minor units.
	PaymentCeilingMinor int64 `json:"paymentCeilingMinor"`

	// Payments Every payment report, oldest first.
	Payments []InvoicePaymentEntryDto `json:"payments"`

	// DeliveryStatus `not_sent` or `sent`.
	// Example: "not_sent".
	DeliveryStatus string `json:"deliveryStatus"`

	SentToBuyerAt *string `json:"sentToBuyerAt"`

	BuyerDelivery InvoiceBuyerDeliveryDto `json:"buyerDelivery"`

	Reporting InvoiceReportingDto `json:"reporting"`

	// SimpleStatus The one status a person reads. `delivered` only when the tax authority says the buyer received it; `transmitted` when it was sent to the buyer's access point and not yet acknowledged.
	SimpleStatus InvoiceViewDtoSimpleStatus `json:"simpleStatus"`

	// ReportedToNRS The tax authority registered the document; false on a draft.
	ReportedToNRS bool `json:"reportedToNrs"`

	// RefundOwed A refund to the buyer is still owed (`refundOwedMinor > 0`).
	RefundOwed bool `json:"refundOwed"`

	Notes *string `json:"notes"`

	PaymentTerms *string `json:"paymentTerms"`

	PurchaseOrderReference *string `json:"purchaseOrderReference"`

	BuyerReference *string `json:"buyerReference"`

	AccountingCost *string `json:"accountingCost"`

	// CreditNoteOf A credit note: the invoice it credits.
	CreditNoteOf *InvoiceDocumentLinkDto `json:"creditNoteOf"`

	// Credits A credit note: the invoice it credits (same as `creditNoteOf`).
	Credits *InvoiceDocumentLinkDto `json:"credits"`

	// Debits A debit note: the invoice it increases.
	Debits *InvoiceDocumentLinkDto `json:"debits"`

	// CancelledByCreditNote A cancelled (or being cancelled) invoice: its credit note.
	CancelledByCreditNote *InvoiceDocumentLinkDto `json:"cancelledByCreditNote"`

	Verification *InvoiceVerificationDto `json:"verification"`

	FinalisedAt *string `json:"finalisedAt"`

	// SubmissionDueAt When a document issued without a buyer tax id (B2C) and not yet submitted must be submitted to the tax authority by: `finalisedAt` plus the jurisdiction window (24 hours in Nigeria). Null when it is signed, being submitted, a draft, cancelled, or of another kind.
	SubmissionDueAt *string `json:"submissionDueAt"`

	CancelledAt *string `json:"cancelledAt"`

	// CreatedBy Who created the document.
	CreatedBy InvoiceActorDto `json:"createdBy"`

	// SubmittedBy Who submitted it to the tax authority; null while never submitted.
	SubmittedBy *InvoiceActorDto `json:"submittedBy"`

	CreatedAt string `json:"createdAt"`

	UpdatedAt string `json:"updatedAt"`

	// Version The concurrency token: send it back as `If-Match: "<version>"` (also the `ETag`).
	Version int64 `json:"version"`
}

